# aeneid-057 (VIII.1-101): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Tiberinus. Sus alba'
PART = "The Tiber's Promise (VIII.1–101)"
TITLE_EN = "The Tiber's Promise — Aeneid VIII.1–101"
ABOUT = ("Book VIII opens with Italy arming. Turnus raises the standard of war, all Latium swears itself into a league, and Venulus "
"is sent to Diomedes, the Greek who once fought Aeneas at Troy, to ask for his help. Aeneas, his mind darting this way and that like "
"light thrown back from water onto a ceiling, lies down at night on the bank of the Tiber, and the river-god himself rises from among "
"the poplars to speak to him: Aeneas has come home, the anger of the gods is spent, and allies are waiting upstream in Evander, an "
"Arcadian king whose little town of Pallanteum stands on the Palatine, the hill that will be the heart of Rome. The god repeats "
"Helenus's sign of the white sow with her thirty young (lines Greenough brackets as spurious) and tells Aeneas to win Juno over with "
"prayer. At dawn Aeneas prays to the river, finds the sow and sacrifices her to Juno; the Tiber stills his current, and two ships row "
"upstream through woods that marvel at the sight, until at noon they see the scattered roofs of a poor settlement where Rome's power "
"would one day rise to the sky. Book VIII, with its walk over the site of Rome and the shield of Aeneas, is the most Roman book of the poem.")

U = [
(3, 'arma,',
 "When the signal of war from Laurentum's citadel Turnus\nhad raised, and with hoarse blare the horns had sounded,\nand when he roused his eager horses and when he clashed his arms,",
 "When Turnus had raised the standard of war on the citadel of Laurentum, and the horns had sounded their harsh blare, when he had roused his fiery horses and clashed his arms,",
 """Book VIII opens on the war that Juno let loose at the end of Book VII, when the gates of Janus were opened (7.607–615) and the Italians mustered. 'Ut' with the perfect indicative is 'when', 'as soon as'; three clauses, 'ut… utque… utque', pile up before the main verb arrives in 4. 'Laurenti… ab arce', 'from the citadel of Laurentum', Latinus's city, 'Laurenti' an adjective. 'belli signum', the standard hoisted as the call to arms. 'rauco… cantu', 'with hoarse note'; compare 'cornua rauco' at 7.615. 'strepuerunt' is the full perfect ending, beside the '-ere' forms you have met so often. 'acris… equos', accusative plural in '-is' (= 'acres'). 'impulit arma', 'struck his arms', spear clashed on shield as a signal."""),
(6, 'effera.',
 "at once troubled were their minds; together, all, in tumult\nswears a league anxious Latium, and rages the youth,\nwild.",
 "at once all minds were in turmoil; all Latium joined in a sworn league amid anxious uproar, and its young men raged in their wildness.",
 """'extemplo', 'immediately'. 'turbati animi', supply 'sunt': the main clause at last. 'simul', 'at the same time'. 'omne… Latium' frames the phrase; 'tumultu… trepido', 'in alarmed uproar': 'tumultus' was the Roman word for a sudden war in Italy itself, when the usual exemptions from service lapsed. 'coniurat', 'swears together': in such a crisis the levy took the military oath in a body, not man by man (Servius, from memory). 'saevit… iuventus effera', 'the young men rage, wild', 'iuventus' a collective singular, with 'effera' carried over into the next line for weight (enjambment) and the sentence stopping short after it."""),
(8, 'agros.',
 "The leaders foremost, Messapus and Ufens\nand the scorner of the gods Mezentius, from all sides gather\nforces, and the broad empty of their tillers fields.",
 "The foremost captains, Messapus and Ufens and Mezentius who despises the gods, gather troops from every side and strip the broad fields of their farmers.",
 """All three come from the catalogue at the end of Book VII: Mezentius, the Etruscan tyrant, led it off (7.647–648, where he is 'contemptor divom'); Messapus, the horse-tamer, son of Neptune, and Ufens of the Aequi came after. 'deum', the old genitive plural (= 'deorum'). 'cogunt auxilia', 'muster forces', 'auxilia' here simply troops. 'vastant cultoribus agros', 'they empty the fields of their tillers', 'cultoribus' an ablative of separation: 'vasto' keeps its first sense, 'make empty' (Lewis & Short), and the farmers go to war."""),
(9, 'urbem,',
 "Is sent also, to great Diomedes' city, Venulus,",
 "Venulus too is sent to the city of great Diomedes,",
 """The print has 'mittitur', lowercase after the full stop that ends 8, a misprint for 'Mittitur', corrected here; t keeps the print, because t must match the pinned source; l and i begin with a capital. 'et', 'also', 'too'. 'Diomedis… ad urbem', 'to the city of Diomedes', the preposition between the adjective and its noun. Diomedes, one of the greatest Greek fighters at Troy, had settled in Apulia in the south-east of Italy and founded Argyripa (11.246–247). In Iliad 5 (from memory) he struck Aeneas down with a boulder, and Aeneas was saved only by his mother Venus, whom Diomedes wounded too: the Latins hope that an old enemy of the Trojans will join them. His answer comes back in Book XI."""),
(14, 'nomen.',
 "to seek help, and that in Latium the Teucrians are settling,\nthat Aeneas, brought by his fleet, his conquered household gods\nis bringing in, and says that he by the fates is called for as king,\nto inform him, and that many nations attach themselves to the man,\nthe Dardanian, and that widely in Latium his name is growing.",
 "to ask for aid and to make plain to him that the Trojans are planting themselves in Latium, that Aeneas has come with his fleet, bringing in his conquered household gods and claiming that fate calls for him as king, that many peoples are joining the Dardanian, and that his name is spreading far and wide through Latium.",
 """'qui petat… edoceat', a relative clause of purpose, 'to seek… and to inform', the subjunctive marking what Venulus is sent to do. 'edoceat' is held back to 13, and all between is the message, in indirect statement: 'Teucros consistere', 'that the Trojans are taking their stand'; 'Aenean… inferre', 'that Aeneas is bringing in'; 'se… posci', 'that he is demanded'; 'gentis… se adiungere', 'that peoples are attaching themselves'; 'nomen increbrescere', 'that his name is growing'. 'Aenean', Greek accusative. 'classi', ablative in '-i', 'by fleet'. 'victos… penatis', 'his conquered gods', Juno's own sneer ('victosque Penates', 1.68); 'penatis', accusative plural in '-is'. 'fatis', 'by the fates', ablative without 'a'. 'viro… Dardanio', dative with 'adiungere', split across the line."""),
(17, 'Latino.',
 "What he is building by these beginnings, what, if Fortune should follow,\noutcome of the fight he desires, more plainly to himself\nthan to Turnus the king or to the king appears, Latinus.",
 "What Aeneas is building towards with these first moves, and what outcome to the fighting he wants if Fortune goes with him, must be plainer to Diomedes himself than to King Turnus or to King Latinus.",
 """The message goes on, with 'edoceat' still understood: 'quid struat… quem… eventum… cupiat', indirect questions, 'what he is building… what result he wants', in the subjunctive; 'si Fortuna sequatur', 'if Fortune should go with him', is subjunctive too, as a clause inside indirect speech. 'apparere', infinitive of indirect statement, 'that (these things) show more plainly to (Diomedes) himself': he has fought Aeneas, and knows what a Trojan wants. 'ipsi' is Diomedes. 'Turno regi aut regi… Latino', a chiasmus, the two kings set crosswise. 'manifestius', comparative adverb. Elisions 'regi aut', 'regi apparere'."""),
(18, 'Latium.',
 "Such things throughout Latium.",
 "So things went throughout Latium.",
 """A new paragraph in Greenough, and the scene turns to the Trojans. 'Talia per Latium', 'such things (were done) throughout Latium', with the verb left out: a brisk close to a section, the same kind of ellipsis as 'haec secum'. The next sentence begins in the same line."""),
(20, 'illuc.',
 "Which the Laomedontian hero,\nall of it seeing, on a great tide of cares is tossed,\nand his mind now this way, swift, now divides it that way.",
 "Seeing it all, the Trojan hero is tossed on a great tide of cares, and sends his quick mind darting now this way, now that.",
 """'Quae… cuncta', a connecting relative, 'all these things'. 'Laomedontius heros', 'the Laomedontian hero': Laomedon, Priam's father, was the king of Troy for whom its walls were built, and the epithet means simply 'Trojan' (Aeneas descends from Assaracus, a brother of Laomedon's father). 'magno curarum fluctuat aestu', 'he heaves on a great surge of cares', a sea metaphor. This line and the next one and a half repeat word for word what was said of Aeneas when Mercury ordered him to leave Carthage (4.285–286): the same hero, the same divided mind. 'dividit', 'parts', sending 'animum… celerem', 'his quick mind', 'huc… illuc', 'here… there'."""),
(25, 'tecti.',
 "And into directions he snatches it various, and through everything turns it:\njust as, of water, the trembling, in basins when light of bronze,\nby the sun struck back or by the image of the radiant moon,\nflits over all, far and wide, places, and now up into the air\nis lifted and strikes of the topmost the panelled ceiling of the roof.",
 "He snatches it now to one side, now to another, and turns everything over: as when the quivering light of water in a bronze basin, thrown back by the sun or by the image of the shining moon, flits far and wide over every place, and now rises into the air and strikes the panels of the ceiling high above.",
 """'In partis… varias', 'in different directions', 'partis' accusative plural in '-is', split from its adjective. The simile comes from Apollonius of Rhodes, where Medea's heart darts like a sunbeam thrown back from water in a pail (Argonautica 3, from memory); Virgil makes it a picture of a restless, flickering mind. 'sicut… ubi', 'just as when', with 'ubi' held back. 'aquae… labris… aenis', 'of water in bronze basins', interwoven with 'tremulum… lumen', 'the quivering light'. 'sole repercussum', 'struck back by the sun', reflected; 'imagine lunae', 'by the moon's reflection'. 'lacuaria' is Greenough's spelling of 'laquearia', 'panelled ceiling', five syllables, la-cu-a-ri-a. 'summi… tecti', 'of the top of the house'. Elision 'repercussum aut'."""),
(27, 'habebat:',
 "Night it was, and the weary creatures through all the lands,\nof birds and of beasts the race, deep sleep was holding:",
 "It was night, and over all the earth deep sleep held the weary creatures, the tribes of birds and beasts:",
 """'Nox erat', a classic scene-setting opening, used for Dido's sleepless night (4.522); the sleeping world set against the one who cannot rest is an old epic contrast (Homer has it of Agamemnon, Iliad 10, from memory). 'terras… per omnis', 'through all the lands', 'omnis' accusative plural in '-is', with 'per' set between. 'animalia fessa', 'tired living things', with 'alituum pecudumque genus', 'the race of birds and beasts', in apposition; both are objects of 'habebat'. 'alituum' is an old poetic genitive plural of 'ales', 'bird', for the usual 'alitum', four syllables here (a-li-tu-um). 'pecudum', 'of beasts', herds and flocks. 'sopor altus', 'deep sleep', the subject, last."""),
(30, 'quietem.',
 "when father, on the bank and under the cold sky's vault,\nAeneas, troubled in his heart by grim war,\nlay down, and late gave through his limbs rest.",
 "when father Aeneas, his heart troubled by the grim war, lay down on the river-bank under the vault of the chill sky and at last let rest spread through his limbs.",
 """'cum… procubuit', the 'inverted cum' with the indicative: the scene is set first and the event comes in the 'cum' clause ('Nox erat… cum…', 'it was night… when'). 'pater… Aeneas', 'father Aeneas', the title of the founder and leader of his people, with the name held over to the next line. 'gelidi… aetheris axe', 'under the axle of the cold sky', the vault of heaven turning on its axis. 'pectora', accusative of respect with 'turbatus', 'troubled in his breast', the Greek construction you have met often. 'seram… quietem', 'late rest', sleep that comes deep in the night. 'dedit per membra', 'gave (rest) through his limbs'. The bank is the Tiber's, where the Trojan camp lies (Book VII)."""),
(33, 'visus;',
 "To him the god himself of the place, from his river, Tiberinus, his pleasant one,\namong the poplar, aged, himself to raise leaves\nseemed;",
 "To him the very god of the place, Tiberinus, appeared, an old man rising from his lovely stream among the poplar leaves;",
 """'Huic', 'to him', with 'visus (est)', 'seemed', 'appeared'. 'deus ipse loci', 'the god of the place himself': every Roman spot had its presiding spirit. 'Tiberinus', the god of the Tiber, Rome's river. 'fluvio… amoeno', 'from his pleasant river', an ablative of separation with 'se attollere', 'to raise himself', the two words framing the line. 'populeas inter… frondes', 'among the poplar leaves', the preposition after the adjective (anastrophe). 'senior', comparative used for 'old'. Gods who come in the night to a sleeper are Homeric (the dream sent to Agamemnon, Iliad 2, from memory); a river-god speaking to a hero recalls Scamander and Achilles (Iliad 21, from memory), there in rage, here in kindness."""),
(35, 'dictis:',
 "him, fine, in a grey-green was veiling robe\nlinen, and his hair shady was covering reed;\nthen thus to address him and his cares with these to take away words:",
 "fine linen draped him in a sea-grey mantle, and shady reeds covered his hair; then he seemed to speak to him, and to lift away his cares with these words:",
 """'eum… velabat… carbasus', 'fine linen veiled him': 'carbasus' (feminine, from the Greek word for flax) is the subject, held over to 34, and 'tenuis', 'fine', agrees with it (three syllables, te-nu-is). 'glauco… amictu', 'in a blue-grey garment', the colour of river water. 'crinis', accusative plural in '-is', 'his hair'; 'umbrosa… harundo', 'shady reed', a river-god's crown. 'tum sic adfari… et… demere', infinitives still governed by 'visus', 'then (he seemed) to speak thus and take away'. 'adfari' is Greenough's spelling of 'affari'. 'his… dictis', 'with these words', framing the clause. Elision 'adfari et'."""),
(39, 'penates;',
 "“O sprung from the race of gods, who the Trojan city from her enemies\nbring back to us, and everlasting Pergamum preserve,\nawaited by the Laurentine soil and by the Latin fields,\nhere for you a sure home, sure — do not give up — your household gods;",
 "“Son of the race of gods, you who bring the city of Troy back to us out of the hands of her enemies and keep her citadel alive for ever, you whom the soil of Laurentum and the fields of Latium have long awaited, here is your sure home, and here — do not give up — your household gods are sure;",
 """A new paragraph in Greenough: the river-god's speech. 'sate', vocative of 'satus', participle of 'sero', 'sown', 'sprung'; 'gente deum', ablative of origin, 'deum' the old genitive plural: Aeneas is Venus's son. 'revehis', 'you bring back': Dardanus, Troy's founder, was born in Italy (7.205–211), so Troy is coming home. 'Troianam ex hostibus urbem', 'the Trojan city (rescued) from her enemies'. 'Pergama', neuter plural, Troy's citadel, here Troy itself. 'exspectate', vocative participle, 'awaited', with 'solo Laurenti arvisque Latinis' as datives of agent. 'hic tibi certa domus', supply 'est', dative of possession. 'ne absiste', 'do not give up', 'ne' with the imperative, a poetic prohibition, elided 'n(e) absiste'."""),
(41, 'deum.',
 "and do not by war's be frightened threats: the swelling, all of it, and the angers\nhave withdrawn, of the gods.",
 "and do not be frightened by the threats of war: all the swelling wrath and anger of the gods has passed.",
 """'neu… terrere', 'and do not be frightened': 'terrere' here is not the infinitive but the passive imperative singular, 'be frightened', with 'neu', 'and not', carrying on the prohibition of 'ne absiste'. 'tumor', 'swelling', the gods' anger (Juno's above all) pictured as swollen water, fitting in a river's mouth. 'concessere' = 'concesserunt', 'have given way'; 'deum' = 'deorum'. Line 41 is a half-line (hemistich), one of the unfinished lines the poem kept when it was published after Virgil's death without his final revision (as the ancient Life reports, from memory). The scanner cannot resolve it as a hexameter for that reason. The Tiber's assurance is premature: Juno's anger is not spent, and he will tell Aeneas to placate her (60)."""),
(45, 'nati.]',
 "[And soon for you, lest you think idle these things sleep is inventing,]\n[on the shore, huge, found under the holm-oaks, a sow,]\n[of thirty heads a litter having brought forth, will lie,]\n[white, on the ground reclining, white about her teats her young.]",
 "[And soon, so that you may not think that sleep is shaping idle fancies, you will find a huge sow lying under the holm-oaks on the shore, mother of a litter of thirty, a white sow stretched on the ground, with her white young about her teats.]",
 """Greenough brackets 42–49 as spurious, so every line of it is printed in [ ] (on the last bracketed line see 49–50). These four lines repeat, almost word for word, the sign Helenus gave Aeneas at 3.390–392, which is why they have been suspected; but the sow appears at 81–85, so something like them is needed here, and many editors (from memory) keep them as Virgil's own repetition. 'Iamque', 'and presently'. 'tibi', 'for you', you will see. 'ne… putes', negative purpose. 'haec fingere somnum', accusative and infinitive, 'that sleep invents these things', 'vana' predicative, 'as idle'. 'litoreis… sub ilicibus', 'under the shore oaks'. 'triginta capitum fetus', 'a litter of thirty head', genitive of description; 'enixa', 'having given birth', from 'enitor'. 'sus', a monosyllable ending the line, as at 83."""),
(49, 'cano.',
 "[Here the place of the city will be, that the sure rest from toils,]\n[from which, as thrice ten come round years, a city]\n[Ascanius will found, of glorious name, Alba.]\n[No uncertain things I sing.",
 "[This will be the site of your city, this your sure rest from toil; and from this sign, when thirty years have come round, Ascanius will found a city of glorious name, Alba. It is no doubtful thing I foretell.",
 """Still within Greenough's brackets. Line 46 is Helenus's 3.393 again, with 'Hic' for 'is', and it sits oddly here, where the Trojans already have their camp; it is the line editors most often doubt (from memory). 'requies ea certa laborum', 'that (will be) sure rest from toils', 'ea' attracted to the gender of 'requies'. 'ex quo', 'from which (sign)'. 'ter denis… redeuntibus annis', ablative absolute, 'when thrice ten years come round', 'deni' a distributive: the thirty young are thirty years, the time Jupiter gave Ascanius before moving his kingdom from Lavinium to Alba (1.269–271). 'clari… cognominis', genitive of description, 'of glorious name': Alba is 'white', named for the sow. 'cano', 'I sing', of prophecy."""),
(50, 'docebo.',
 "Now by what means what presses on you]\nyou may carry through as victor, in few words (attend!) I shall teach.",
 "Now how you may deal with what presses on you] and come out the victor, I shall show you in a few words — attend.",
 """The bracket closes after 'instat', at the end of 49, because the archive brackets whole lines, but the second half of 49 cannot be spared: 'qua ratione quod instat expedias', 'by what means you may clear what presses on you', is an indirect question that depends on 'docebo' in 50, and 'expedias victor' has nothing to hang on without it. So read 'Nunc… instat' with 50, whatever one thinks of 42–49. Notice too that 'concessere deum' (41) and 'Nunc qua ratione quod instat' together scan as one complete hexameter, a hint at how the passage may have grown (an observation, not Greenough's). 'quod instat', 'what is at hand'. 'expedias', subjunctive of the indirect question. 'victor', predicative, 'as victor'. 'paucis', supply 'verbis'. '(adverte)', supply 'animum', 'attend', a parenthesis Greenough marks with round brackets."""),
(54, 'Pallanteum.',
 "Arcadians on these shores, a race from Pallas sprung,\nwho King Evander as companions, who his standards followed,\nchose a place and set on the hills a city,\nfrom Pallas's, their forefather's, name, Pallanteum.",
 "Arcadians, a race descended from Pallas, who followed King Evander as his companions and under his standards, have chosen a site on these shores and set a city on the hills, naming it Pallanteum after their forefather Pallas.",
 """'Arcades', Greek nominative plural, 'Arcadians', from Arcadia in the mountains of the central Peloponnese. 'his oris', 'on these shores', ablative of place. 'genus… profectum', 'a race set out from Pallas', in apposition. 'qui… comites, qui signa secuti', 'who followed King Evander as companions, who followed his standards', 'secuti (sunt)' serving both. 'Euandrum', Greenough's form of Evander, scans with 'Eu' as one syllable, 'regem' elided before it. 'delegere… posuere', '-ere' perfects. 'Pallantis proavi de nomine', 'from the name of their forefather Pallas'. Pallanteum stands on the Palatine, where Augustus would live; the Romans derived 'Palatium' from it. The line has a spondee in the fifth foot and ends on the four-syllable Greek name Pal-lan-te-um: a 'spondaic' line, a Greek effect."""),
(56, 'iunge.',
 "These a war constantly wage with the Latin race;\nthese to your camp bring as allies, and treaties join.",
 "They are forever at war with the Latin people; bring them into your camp as allies and bind them to you by treaty.",
 """'Hi… hos', 'these… these', the anaphora pressing the point. 'bellum… ducunt', 'drag out a war', 'ducere' of prolonging. 'adsidue' is Greenough's spelling of 'assidue', 'constantly'. 'castris', dative, 'to your camp'. 'adhibe socios', 'bring in as allies', 'socios' predicative. 'foedera iunge', 'join treaties', make an alliance, 'foedera' a poetic plural. The enemy of the Latins is the Trojans' natural friend. Elision 'bellum adsidue'."""),
(58, 'amnem.',
 "I myself you by the banks and by the straight stream will lead,\nso that the opposing with oars you may overcome, carried upstream, current.",
 "I myself will guide you between my banks and straight up my stream, so that your oars may carry you up against the current and master it.",
 """'Ipse ego', 'I myself', emphatic: the river will help in person. 'ripis et recto flumine', 'by my banks and straight stream', ablatives of the way by which. 'ut' is held back inside its clause, a common order in verse: 'ut superes… subvectus', 'so that, carried up, you may overcome', a purpose clause. 'adversum… amnem', 'the current against you', framing the line. 'sub-vectus', 'carried up', the prefix of motion upward, here upstream. 'remis', 'with oars', ablative of means."""),
(61, 'votis.',
 "Rise, come, son of a goddess, and as the first are setting stars\nto Juno bring duly prayers, and her anger and her threats\nwith suppliant overcome vows.",
 "Up, son of the goddess, come; as the first stars set, bring your prayers in due form to Juno, and overcome her anger and her threats with humble vows.",
 """'Surge age', 'up, come', 'age' an imperative used as an interjection. 'nate dea', 'born of a goddess', vocative with an ablative of origin, a regular address to Aeneas. 'primis… cadentibus astris', ablative absolute, 'as the first stars set', at the coming of dawn. 'rite', 'duly', with the proper forms. The Tiber repeats Helenus's chief command (3.437–439: pray to Juno first, and 'supplicibus supera donis', 'overcome her with suppliant gifts'); here 'votis', 'vows'. 'iramque minasque', the double '-que'. 'supera', imperative, 'overcome'."""),
(62, 'persolves.',
 "To me as victor honour\nyou will pay in full.",
 "When you have won, you will pay me the honour that is my due.",
 """'Mihi… honorem persolves', 'you will pay me honour in full', the future used as a mild command, or a promise claimed in advance. 'victor', predicative, 'as victor', 'when you have won'. 'per-solves', 'pay off completely', a word from the language of vows: the god asks for his share when the prayer is answered. Aeneas makes just such a promise at 76."""),
(64, 'amnis.',
 "I am he whom with full stream you see\ngrazing the banks and the rich tilled lands cutting through,\nthe blue Thybris, to heaven most pleasing river.",
 "I am the one you see brushing the banks with my brimming stream and cutting through the rich ploughlands, the sea-blue Tiber, the river dearest to heaven.",
 """The god names himself last, in the Homeric manner (Scamander does the same to Achilles in Iliad 21, from memory). 'Ego sum… quem… cernis', 'I am (the one) whom you see', the antecedent left out. 'pleno… flumine', 'with full stream', ablative of manner. 'stringentem ripas', 'grazing the banks', the river brimming to its edges; 'pinguia culta', 'rich cultivated lands', 'culta' a neuter plural participle used as a noun. 'Thybris' is the Greek form of the Tiber's name, the form of the poem's grand moments, as in Creusa's prophecy (2.782). 'caelo', dative with 'gratissimus', 'most pleasing to heaven': Rome's river will be the gods' favourite."""),
(65, 'exit.”',
 "Here for me a great home — for lofty cities a head — comes forth.”",
 "Here my great house rises, the head of lofty cities.”",
 """The speech ends on a line much argued over. 'Hic', 'here', on this spot. 'mihi magna domus', 'a great home for me', dative of possession. The difficulty is 'celsis caput urbibus exit'. If 'caput' is 'head' in the sense of 'capital', the clause looks ahead to Rome, 'a head for lofty cities', rising ('exit', 'comes forth') here beside the god. If it is 'source', as a river's 'caput' often is, it says that the Tiber rises among lofty cities (the hill-towns upstream), and the line sets his source against his great home here. The translation takes the first, which suits the god's pride in Rome; the second has the ordinary river-sense of 'caput' on its side. The closing mark ends the Tiber's speech."""),
(67, 'reliquit.',
 "He spoke, then in his pool the river hid himself, his deep one,\nthe lowest depths seeking; night Aeneas and sleep left.",
 "He spoke, and then the river-god plunged into his deep pool, making for the depths; and night and sleep left Aeneas.",
 """A new paragraph in Greenough. 'Dixit', 'he spoke', the regular close of a speech. 'deinde' is two syllables here (synizesis, dein-de). 'lacu… alto', 'in his deep pool', 'lacus' used of any body of water, here the river's bed. 'se condidit', 'hid himself', 'plunged'. 'ima petens', 'seeking the depths', 'ima' neuter plural of 'imus'. 'nox… somnusque', two subjects with a singular verb, 'reliquit', agreeing with the nearer. 'Aenean' is the Greek accusative again (Ae-ne-an, the Ae one syllable)."""),
(70, 'voces:',
 "He rises, and, of the heavenly looking at the rising sun\nthe light, duly in hollowed water from the river palms\nholds up, and such pours out to the sky words:",
 "He rises, and, looking towards the rising light of the sun in the heavens, duly lifts water from the river in his cupped palms and pours out these words to the sky:",
 """'aetherii… orientia solis lumina', 'the rising light of the heavenly sun', adjectives and nouns spread across the line; facing the sunrise was the proper posture for prayer at dawn. 'rite', 'with due rite'. 'cavis… palmis', 'in hollowed palms', framing 'undam de flumine', 'water from the river': water taken up before prayer is a purification, and here it is the god's own water. 'sustinet', 'holds up'. 'talis… voces', 'such words', accusative plural in '-is'. 'effundit', 'pours out', a strong verb for prayer. The prayer that follows is a formal one."""),
(73, 'periclis.',
 "“Nymphs, Laurentine nymphs, from whom to the rivers is their race,\nand you, O Thybris, father, with your holy stream,\nreceive Aeneas and at last ward him from dangers.",
 "“Nymphs, nymphs of Laurentum, from whom the rivers have their birth, and you, father Tiber, with your holy stream, receive Aeneas and keep him at last from danger.",
 """Aeneas's prayer has the shape of a Roman prayer: the powers invoked, the request, the promise. 'Nymphae, Laurentes nymphae', the name repeated in solemn address. 'genus amnibus unde est', 'from whom the rivers have their origin', 'amnibus' dative of possession, 'unde' held back: the nymphs are the springs from which rivers rise. 'Thybri', Greek vocative of 'Thybris', with 'tuque' elided into 'o'. 'genitor', 'father', the Romans' title for their river. 'tuo… cum flumine sancto', god and water addressed together. 'periclis', syncopated for 'periculis', ablative of separation with 'arcete', 'keep (him) from dangers'. Aeneas speaks of himself in the third person, as a suppliant does. Elisions 'accipite Aenean', 'tandem arcete'."""),
(77, 'aquarum.',
 "In whatever you a pool, pitying our troubles,\nspring holds, from whatever ground, most beautiful, you come out,\nalways with my honour, always you will be celebrated with gifts,\nhorned river, of the western ruler waters.",
 "In whatever spring the pool holds you, you who pity our hardships, from whatever ground you issue in your beauty, always with my worship, always with my gifts you will be honoured, horned river, lord of the waters of the west.",
 """'Quo te cumque… fonte', 'in whatever spring', 'quocumque' split around 'te' (tmesis): Aeneas does not know the god's source, so the prayer covers every possibility, as Roman prayers liked to. 'lacus', nominative, the pool that 'holds' him ('tenet'); the Latin Library's 'tenent' makes 'lacus' plural, 'whatever pools hold you', with no real change of sense. 'miserantem incommoda nostra', 'pitying our troubles', agreeing with 'te'. 'celebrabere' = 'celebraberis', future passive with the '-re' ending; 'semper… semper', anaphora. 'corniger', 'horned': river-gods were shown with horns, for the bull's strength of their streams. 'hesperidum… aquarum', 'of the western waters', 'hesperidum' a genitive plural adjective from 'Hesperis', 'western', agreeing with 'aquarum' (Greenough prints it lowercase, not the Hesperides)."""),
(78, 'firmes.”',
 "Be present, O, only, and more nearly your divine will confirm.”",
 "Only be with me, I pray, and come nearer to make your divine promise sure.”",
 """'Adsis… firmes', present subjunctives of wish, 'may you be present… may you confirm', the usual form of a prayer's request. 'o tantum', 'oh, only (this)'. 'propius', 'more nearly': come closer than in a dream, and give a sign. 'tua numina', 'your divine will', 'numen' in its root sense of the god's nod (from 'nuo', 'nod'), here the promises of the dream, a poetic plural. Elision 'tantum et'. The closing mark ends the prayer."""),
(80, 'armis.',
 "Thus he speaks, and two he chooses from the fleet biremes,\nand with oarage fits them, his comrades at the same time equips with arms.",
 "So he speaks, and chooses two biremes from the fleet and fits them with oars and crews, and at the same time arms his comrades.",
 """The print has 'sic', lowercase after the full stop and closing mark at the end of 78, a misprint for 'Sic', corrected here; t keeps the print, because t must match the pinned source; l and i begin with a capital. 'memorat', 'he says', a verb of speaking in epic. 'geminas… biremis', 'twin biremes', a pair of ships with two banks of oars, a vessel of Virgil's own day; 'biremis' accusative plural in '-is'. 'legit', present of 'lego', 'chooses'. 'remigio… aptat', 'fits with oarage', 'remigium' covering both the oars and the rowers. 'simul', 'at the same time'. 'instruit armis', 'equips with arms'. Aeneas is following the river-god's advice and going upstream to Evander."""),
(81, 'monstrum;',
 "But look, a sudden and to the eyes wonderful portent;",
 "And suddenly, see — a portent, wonderful to behold;",
 """A new paragraph in Greenough. 'Ecce autem', 'but look!', the epic signal of a sudden turn, bringing the scene before your eyes. Supply 'est' or 'apparet'. 'monstrum', 'portent', a sign of the gods' will, from 'moneo', 'warn', in the Romans' own etymology. 'oculis', dative of reference with 'mirabile', 'wonderful to the eyes'. Elisions 'subitum atque oculis'."""),
(83, 'sus.',
 "white, through the wood, with her young of one colour, white,\nlay stretched, and on the green shore is seen a sow.",
 "gleaming white through the wood, with her litter as white as herself, a sow lay stretched out, and was seen on the green shore.",
 """The sign of 43–45 (and of Helenus, 3.389–393) comes true. The subject, 'sus', 'sow', is held to the very end, a single monosyllable closing the hexameter, a blunt, homely ending that Virgil uses rarely and on purpose (as at 43). 'candida… concolor albo', 'white… the same colour as her white litter', 'concolor' 'of like colour', with 'cum fetu… albo'. 'procubuit', perfect, 'had lain down', then the present 'conspicitur', 'is seen': the tenses move from the sow's lying there to the moment she is found. 'viridi… in litore', 'on the green shore', the riverbank. Elision 'viridique in'."""),
(85, 'aram.',
 "Whom dutiful Aeneas to you, indeed, to you, greatest Juno,\nsacrifices, the rites performing, and with her brood sets at the altar.",
 "Her dutiful Aeneas offers up to you, to you indeed, mightiest Juno, performing the sacred rites, and sets her with her litter at the altar.",
 """'Quam', connecting relative, 'and her'. 'pius Aeneas', the hero's standing epithet, here at its most literal: duty to the gods. 'tibi enim, tibi', 'to you, indeed, to you': 'enim' keeps its old sense, 'truly', 'indeed', not 'for' (Lewis & Short gives this use), and the address to Juno with 'tibi' repeated stresses that the victim goes to her, the hostile goddess whom the Tiber (60) and Helenus before him (3.437–438) told Aeneas to placate. 'maxuma' is Greenough's spelling of 'maxima'. 'mactat', 'sacrifices'. 'sacra ferens', 'performing the rites'. 'cum grege', 'with the flock', the litter. 'sistit ad aram', 'stands (her) at the altar': the sacrifice is named before the step that precedes it, the chief act first (hysteron proteron)."""),
(89, 'abesset.',
 "Thybris that, as long as it is, night, his swelling stream\nsoothed, and with silent flowing back so stood still wave\nthat, gentle, in the manner of a pond and a calm marsh,\nhe levelled his surface with his waters, so that from the oar struggle should be absent.",
 "All that night long the Tiber calmed his swollen stream, and flowing back with silent water stood so still that he lay gentle as a pond or a quiet marsh and smoothed his surface flat, and the oar had no struggle.",
 """'Thybris… fluvium… tumentem leniit', 'the Tiber calmed his swelling stream', god and water distinguished as in 72. 'ea… nocte, quam longa est', 'that night, all its length', 'through the whole night'; 'leniit', perfect of 'lenio' (le-ni-it). 'tacita refluens… unda', 'flowing back with silent wave', ablative of manner. 'ita… ut… sterneret', a result clause, 'so (still) that he spread level'; 'mitis', 'gentle', nominative, of the god. 'in morem stagni placidaeque paludis', 'in the manner of a pond and a calm marsh'. 'remo ut luctamen abesset', a second result clause, 'ut' held back: 'so that struggle was absent from the oar', 'remo' dative; 'luctamen', a poetic noun, 'effort'. Elision 'longa est'."""),
(91, 'abies;',
 "So the journey begun they speed, with favouring sound;\nglides, pitched, over the waters the fir;",
 "So they hurry on with the voyage they have begun, cheered on their way; the pitch-smeared fir glides over the water;",
 """'Ergo', 'therefore', with the river stilled. 'iter inceptum celerant', 'they speed the journey begun'. 'rumore secundo', 'with favouring sound', is an old phrase (Ennius used it, from memory) and an uncertain one here: it may be the cheerful shouts of the rowers, a good report or omen, or the gentle murmur of the water under the keels. 'labitur… abies', 'the fir glides', 'abies', 'fir', for the ship built of it (metonymy), three syllables here. 'uncta', 'smeared', with pitch, as hulls were. 'vadis', 'over the waters', ablative of the way; 'vada' are properly shallows, in verse often any water."""),
(93, 'carinas.',
 "wonder even the waves,\nwonders the wood, unused to it, gleaming far off\nshields of men on the river, and painted floating keels.",
 "the very waves are amazed, and the woods, unused to the sight, marvel at the warriors' shields gleaming far down the river and the painted ships afloat on its stream.",
 """'mirantur et undae, miratur nemus', 'even the waves wonder, the grove wonders': the verb repeated with a change of number (anaphora), and the landscape itself astonished, mark the first ships ever to come up the river to the site of Rome. 'insuetum', 'unaccustomed', with 'nemus', or adverbial, 'in unaccustomed wonder'. 'fulgentia… scuta', 'shields shining', hung along the ships' sides; 'virum' = 'virorum'. 'innare', 'to float on', with 'fluvio' dative; 'scuta… pictasque… carinas… innare' is an accusative and infinitive after 'miratur', 'wonders that shields and painted keels float on the river'. 'carinas', 'keels', ships. Elision 'pictasque innare'."""),
(96, 'silvas.',
 "They with rowing night and day wear out,\nand the long get past windings, and by various are covered\ntrees, and the green cut on the calm surface woods.",
 "On they row, wearing out the night and the day, and round the long bends, shaded by trees of every kind, they cut through the green woods mirrored on the calm water.",
 """'Olli', an archaic form of 'illi', 'they' (nominative plural), which Virgil keeps for an old-fashioned, solemn ring. 'remigio', 'with rowing', ablative of means. 'noctemque diemque fatigant', 'they wear out night and day', a bold phrase: they row so long that the hours themselves grow tired; the double '-que'. 'longos superant flexus', 'they get past the long windings' of the river. 'variis… arboribus', 'by trees of many kinds'. 'viridis… silvas', accusative plural in '-is': 'they cut the green woods on the calm water', the trees reflected in the still river, so that the ships seem to cut through them. Elision 'placido aequore'."""),
(100, 'habebat:',
 "The sun the middle of the sky had climbed, fiery, circle,\nwhen walls and a citadel far off and scattered, of houses,\nroofs they see, which now Roman power to the sky\nhas made equal; then a poor estate Evander held:",
 "The fiery sun had climbed to the top of the sky's arc when they see far off walls and a citadel and the scattered roofs of houses, which Roman power has now raised as high as heaven, but which then were the poor domain of Evander:",
 """'medium caeli… orbem', 'the middle of the sky's circle', the top of the sun's daily arc: it is noon. 'conscenderat', pluperfect, 'had climbed', followed by 'cum… vident', the inverted 'cum' again (as at 28). 'rara domorum tecta', 'scattered roofs of houses', a straggling settlement. 'quae nunc… tum', 'which now… then', one of the poem's great contrasts of then and now: the poor village on the Palatine is the site of Rome, whose power in Virgil's day 'has made it equal to the sky' ('caelo', dative, with 'aequavit'), with the temples and the house of Augustus. 'res inopes', 'a needy state', 'res' of wealth and power. 'Euandrus', Greenough's form of Evander, 'Eu' one syllable."""),
(101, 'propinquant.',
 "More quickly they turn the prows and to the city draw near.",
 "Swiftly they turn their prows to the bank and draw near the city.",
 """'ocius', comparative adverb, 'more quickly', in verse often simply 'with speed', 'at once'. 'advertunt proras', 'turn their prows (to the land)', 'ad-' of turning towards. 'urbi', dative with 'propinquant', 'approach the city'. The voyage ends in a single line; the meeting with Evander follows in the next part."""),
]

P = A.part('aeneid-057'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
